  "tag": "태그",
  "Edit this subject — name, comment and date": "이 인물 편집 — 이름, 설명, 날짜",
  "Create": "만들기",
  "Merge into an existing tag?": "기존 태그로 병합할까요?",
  "That tag already exists. Merging folds this subject's tag into it: every picture carrying the old one carries the new one instead, along with what it implied and the groups that assigned it.": "그 태그는 이미 있습니다. 병합하면 이 인물의 태그가 그 안으로 접힙니다: 이전 태그를 가진 모든 사진이 대신 새것을 갖게 되며, 함의하던 것과 이를 지정하던 그룹도 함께입니다.",
  "It is also somebody's identity, so the two subjects become one.": "그것은 누군가의 정체성이기도 하므로 두 인물이 하나가 됩니다.",
  "New subject": "새 인물",
  "Somebody or something a picture can be OF": "사진의 대상이 될 수 있는 사람이나 사물",
  "Edit subject": "인물 편집",
  "Exists since": "존재 시작",
  "1975, 7/1999, 14.3.1879": "1975, 7/1999, 14.3.1879",
  "a_tag_name": "a_tag_name",
  "Rename the tag along with the subject": "인물과 함께 태그 이름도 바꾸기",
  "That date doesn't look like a date.": "그 날짜는 날짜처럼 보이지 않습니다.",
  "Merge subjects?": "인물을 병합할까요?",
  "Another subject already has this name and comment. Merging moves everything this one carries onto it: every picture it is in, what its tag implies, and (later) its faces.": "다른 인물이 이미 이 이름과 설명을 갖고 있습니다. 병합하면 이 인물이 가진 모든 것이 그리로 이동합니다: 나오는 모든 사진, 태그가 함의하는 것, 그리고 (나중에) 얼굴들.",
  "The old tag stays behind as an alias, so anything still using it finds the merged subject.": "이전 태그는 별칭으로 남아, 아직 이를 쓰는 것은 병합된 인물을 찾게 됩니다.",
  "No date on this item": "이 항목에 날짜 없음",
  "Set a date": "날짜 지정",
  "Change the date": "날짜 변경",
  "It has no date": "날짜가 없습니다",
  "year, date, or date and time": "연도, 날짜, 또는 날짜와 시간",
  "from the file's EXIF data": "파일의 EXIF 데이터에서",
  "from the event below": "아래 이벤트에서",
  "How old they are in this item": "이 항목에서 그 사람의 나이",
  "Say who this is": "누구인지 말하기",
  "Subjects": "인물",
  "Nothing": "없음",
  "Puts something in front of each group's tags, so a block reads “Alice: blonde hair, dress” instead of “blonde hair, dress”.\n\nThe group's NAME is right when your groups are named for what they show. The SUBJECTS it is about are usually better: a group called “front figure” is bookkeeping, while the subject on it is “Alice” — the word you would actually type at generation time.\n\nA group with no subjects gets no label at all under that choice, rather than quietly falling back to its name.": "각 그룹의 태그 앞에 무언가를 붙여, 블록이 “blonde hair, dress” 대신 “Alice: blonde hair, dress”로 읽히게 합니다.\n\n그룹이 보여 주는 것을 따라 이름 지어졌다면 그룹의 이름이 맞습니다. 그룹이 다루는 인물이 보통 더 낫습니다: “앞쪽 인물”이라는 그룹은 장부 정리일 뿐이고, 그 위의 인물은 “Alice” — 생성 시 실제로 입력할 단어입니다.\n\n그 선택에서 인물이 없는 그룹은 이름으로 조용히 되돌아가는 대신 라벨을 전혀 받지 않습니다.",
  "Say who this group is about": "이 그룹이 누구에 관한 것인지 말하기",
  "What to write in front of a block, as “label: tags”. Nothing by default — a group's name is often for the person tagging rather than for the model.": "블록 앞에 “라벨: 태그” 형태로 무엇을 쓸지입니다. 기본은 없음 — 그룹 이름은 흔히 모델이 아니라 태그를 다는 사람을 위한 것입니다.",
  "Named": "이름 있음",
  "No tag": "태그 없음",
  "A per-item tag group is usually about one thing in the picture — Alice's hair and dress, Bob's hat. Flattened into one comma list, the model is left to work out which adjective belongs to whom, and in a busy image it often gets it wrong.\n\nWith this on, the tags the random pick chose are laid out per group, in the order the pick produced, so shuffling still applies within a block. Tags in no group lead, because they describe the scene the groups sit inside. A tag that is in two groups is written under the first one — the same tag twice reads as emphasis and teaches nothing.": "항목별 태그 그룹은 보통 그림 속 한 가지에 관한 것입니다 — Alice의 머리와 드레스, Bob의 모자. 하나의 쉼표 목록으로 펴 놓으면 어느 형용사가 누구 것인지 모델이 알아내야 하고, 복잡한 이미지에서는 자주 틀립니다.\n\n이것이 켜져 있으면 무작위 추첨이 고른 태그가 그룹별로, 추첨이 만든 순서대로 배치되어, 섞기는 블록 안에서 여전히 적용됩니다. 그룹 없는 태그가 앞장섭니다. 그룹들이 놓인 장면을 설명하기 때문입니다. 두 그룹에 있는 태그는 첫 번째 아래에 쓰입니다 — 같은 태그가 두 번이면 강조로 읽히고 아무것도 가르치지 않습니다.",
  "The string between one group's block and the next. A newline is the default because it is what makes the blocks read as separate statements rather than one longer list.\n\nIf your prompts are consumed somewhere that cannot carry line breaks, a distinctive string such as “ | ” works too — just use the same convention when you write generation prompts.": "한 그룹의 블록과 다음 블록 사이의 문자열입니다. 줄바꿈이 기본값인 것은, 그것이 블록들을 하나의 더 긴 목록이 아니라 별개의 문장들로 읽히게 하기 때문입니다.\n\n프롬프트가 줄바꿈을 담을 수 없는 곳에서 소비된다면 “ | ” 같은 눈에 띄는 문자열도 됩니다 — 생성 프롬프트를 쓸 때 같은 관례를 쓰기만 하세요.",
  "not a face": "얼굴 아님",
  "Fold the selected subjects into one": "선택한 인물을 하나로 접기",
  "Merge subjects": "인물 병합",
  "Keep": "유지",
  "The one that survives. The others' faces, pictures and dates move onto it.": "살아남는 쪽. 나머지의 얼굴, 사진, 날짜가 그리로 이동합니다.",
  "Keep each old tag as an alias, so anything still using it finds the merged subject": "각 이전 태그를 별칭으로 유지 — 아직 쓰는 것은 병합된 인물을 찾게 됩니다",
  "{slug} already belongs to another tag. Pick another name.": "{slug}은(는) 이미 다른 태그의 것입니다. 다른 이름을 고르세요.",
  "{slug} already belongs to another tag — saving offers to merge them.": "{slug}은(는) 이미 다른 태그의 것입니다 — 저장 시 병합할지 묻습니다.",
  "Detect": "감지",
