  "This video can't be played here": "이 동영상은 여기서 재생할 수 없습니다",
  "Its format or codec ({format}) isn't supported by the browser's player. You can still tag the whole item and manage its metadata; drawing timed boxes needs a playable preview.": "형식이나 코덱({format})을 브라우저의 플레이어가 지원하지 않습니다. 항목 전체에 태그를 달고 메타데이터를 관리할 수는 있지만, 시간 지정 박스를 그리려면 재생 가능한 미리보기가 필요합니다.",
