  "Rate on this ranking…": "이 랭킹에서 평가…",
  "Delete “{name}” and its comparisons? This cannot be undone.": "“{name}”과(와) 그 비교를 삭제할까요? 되돌릴 수 없습니다.",
  "Unplaced": "미배치",
  "Ranking order": "랭킹 순서",
  "Take this picture out of the ranking? Its {n} comparisons are deleted and the standings refit.": { "other": "이 사진을 랭킹에서 뺄까요? 비교 {n}건이 삭제되고 순위가 다시 계산됩니다." },
  "Nothing placed yet — compare a few pairs and they appear here, best first.": "아직 순위에 오른 것이 없습니다 — 몇 쌍을 비교하면 가장 좋은 것부터 여기에 나타납니다.",
  "Its pictures cannot all be put in one order yet, so the standings would say more than the comparisons do": "아직 사진을 한 줄로 세울 수 없어, 순위가 비교가 말하는 것보다 더 많은 것을 주장하게 됩니다",
