  "“{name}” is a score tag of the ranking “{ranking}” — scores come from rating pictures, not from assigning the tag": "“{name}”은(는) 랭킹 “{ranking}”의 점수 태그입니다 — 점수는 태그를 할당해서가 아니라 사진을 평가해서 생깁니다",
  "Delete “{name}”, its comparisons and its score tags? The score tags disappear from every picture, and this cannot be undone.": "“{name}”과(와) 그 비교 및 점수 태그를 삭제할까요? 점수 태그가 모든 사진에서 사라지며 되돌릴 수 없습니다.",
