  "Delete the ranking, its comparisons, and its score tags? The score tags disappear from every picture, and this cannot be undone.": "랭킹과 그 비교, 점수 태그를 삭제할까요? 점수 태그는 모든 사진에서 사라지며 되돌릴 수 없습니다.",
  "A ranking places your pictures on an axis — quality, composition, art style — by quick side-by-side comparisons. Rate pairs with the keyboard and every picture gets a score tag (quality:0 … quality:9) that search and training can use, kept up to date automatically.": "랭킹은 빠른 나란히 비교로 사진을 하나의 축(품질, 구도, 그림체) 위에 배치합니다. 키보드로 쌍을 평가하면 각 사진에 점수 태그(quality:0 … quality:9)가 붙고, 검색과 학습에서 쓸 수 있으며 자동으로 최신 상태로 유지됩니다.",
  "New ranking": "새 랭킹",
