  "They are not estimated: the ranking's own score is the number the rules read, since a guess laid over an answer is a worse answer.": "이들은 추정하지 않습니다. 규칙은 랭킹 자체의 점수를 읽습니다. 답 위에 추측을 얹는 것은 더 나쁜 답이기 때문입니다.",
